const src = $json.body ?? $json;
const text = String(src.text ?? src.caption ?? '').slice(0, 4000);
const lower = text.toLowerCase();
let category = 'general';
if (/commande|livraison|retard|client/.test(lower)) category = 'order';
if (/connexion|accès|acces|mot de passe|traiteur|partenaire/.test(lower)) category = 'partner_access';
if (/fournisseur|devis|catalogue|prix|stock|rfq/.test(lower)) category = 'supplier';
if (/rembours|plainte|réclamation|reclamation|litige/.test(lower)) category = 'complaint';
if (/paiement|sumup|stripe|carte/.test(lower)) category = 'payment';
const urgent = /urgent|immédiat|immediat|bloqué|bloque|erreur|panne/.test(lower);
return [{json:{message_id:src.id ?? null,from:src.from ?? null,type:src.type ?? null,text,category,urgent,received_at:src.received_at ?? new Date().toISOString()}}];
